insert into public.application_openings (slug,eyebrow,title,description,accent,details,responsibilities,form_version,form_schema,email_templates,status,opens_at)
select 'events-officer','Officer application','Events officer','Help plan and run GDG UTDallas events, coordinate logistics, and create welcoming experiences for the chapter.','yellow',
'[{"label":"Team","value":"Events"},{"label":"Commitment","value":"Full semester"}]'::jsonb,
'["Plan chapter events and coordinate logistics","Support event setup, check-in, and activities","Work with other teams to deliver welcoming events"]'::jsonb,
1,jsonb_build_object('sections',jsonb_build_array(form_schema->'sections'->0) || '[{"id":"questionnaire","title":"Role questionnaire","description":"Tell us how you would help plan and run chapter events.","fields":[{"id":"motivation","type":"long_text","label":"Why would you like to be an Events officer?","required":true,"max_length":2000},{"id":"event_experience","type":"long_text","label":"Tell us about a time you organized an event or coordinated a team.","required":true,"max_length":2000},{"id":"event_idea","type":"long_text","label":"Describe an event you would like to organize for GDG UTDallas and how you would plan it.","required":true,"max_length":2000},{"id":"time_restrictions","type":"long_text","label":"Do you have any time restrictions we should be aware of?","required":false,"max_length":2000}]},{"id":"agreements","title":"Role agreements","fields":[{"id":"agreement_semester","type":"checkbox","label":"Agreement: I will support the Events team for the full semester, attend required meetings and events, and communicate scheduling conflicts early.","required":true},{"id":"agreement_communication","type":"checkbox","label":"Agreement: I will communicate with teammates, complete assigned tasks on time, and help create welcoming events.","required":true}]}]'::jsonb),
replace(replace(replace(email_templates::text,'Tech officer','Events officer'),'Technical team','Events team'),'technical team','events team')::jsonb,'open',now()
from public.application_openings where slug='tech-officer'
on conflict (slug) do nothing;
